CAT = "dktrJunctions"; SEG = "JNC"
# Afsnit 7.11 to 7.21: junctions, right and left turns, roundabouts, motorways, stopping and
# parking, darkness.
Q = [
("You approach a junction with traffic lights in a heavily loaded lorry. What is a key risk?",
 "Too much speed for the load", ["Stopping too early", "Signalling too soon", "Following the car ahead too far back"],
 "Too high a speed towards a signalled junction is a risk, especially given the load, because a loaded lorry needs a long distance to stop."),
("In most crashes while a lorry drives straight on at a junction, what is true?",
 "The lorry had to give way", ["The other driver had to give way", "The lights had failed", "The lorry was reversing"],
 "Most of these crashes happen at junctions where the lorry has to give way but often drives too fast for the conditions."),
("At junctions, what mistake do lorry drivers tend to make with weaker road users?",
 "Relying on size, not giving way", ["Giving way far too often", "Stopping in the junction", "Driving through far too slowly"],
 "There is a tendency to drive on your own strength against weaker parties and so fail to give way when you must."),
("You pull away into a junction after stopping. Why can your lorry's length be a danger?",
 "Crossing traffic may reach you", ["The trailer may lift", "The brakes may drag", "The mirrors may vibrate out of line"],
 "The lorry's length, any protruding load and its poor acceleration, together with misjudging the speed of crossing traffic, increase the risk of a collision after a stop."),
("In about half of the crashes while a large vehicle turns right, who is the other party?",
 "A cyclist or moped rider", ["An oncoming car", "A pedestrian ahead", "A following lorry or bus"],
 "About half involve a cyclist or moped rider on the vehicle's right whom the driver squeezes or turns across."),
("When a right-turn crash with a cyclist happens, where is the cyclist most often as the turn starts?",
 "At the right front corner", ["Far behind the trailer", "Directly ahead of the cab", "On the lorry's left side"],
 "The cyclist is usually at the vehicle's right front corner when the turn begins, often after waiting at a red light beside the lorry."),
("Your light turns green and you want to turn right. What mistake should you avoid?",
 "Taking green as a free path", ["Waiting far too long on green", "Turning from the left lane", "Signalling too early"],
 "There is a tendency to see green as a sign of a free path to turn right. Cyclists and pedestrians may still be coming through the junction."),
("You wait at a red light to turn right, and cyclists stop beside you. What should you keep doing?",
 "Watch them in the mirrors", ["Edge forward to claim space", "Look only at the lights", "Sound the horn to warn them"],
 "Keep checking through the windows and mirrors, and any camera or sensors, for cyclists and moped riders to the right of the lorry while you wait."),
("You turn right across a cycle track in a lorry. How can you give yourself time to check properly?",
 "Stop before the cyclists' path", ["Turn quickly to clear it", "Sound the horn and go", "Rely on the blind-spot sensor alone"],
 "Turn at a suitably low speed and, if needed, stop before crossing the cyclists' path so there is time for thorough checks."),
("You need to swing out to the left before turning right. How should you do it?",
 "Early, then signal right", ["Late, signalling left", "Early, without signalling", "Late, after starting to turn"],
 "Where you first pull to the left to make a right turn, do it at a good distance from the side road and then signal for the right turn."),
("Your lorry has a long rear overhang. When you turn, who can it endanger?",
 "Vehicles passing alongside", ["Pedestrians ahead", "Your own passengers", "Traffic on another road far off"],
 "Large vehicles with a long rear overhang swing out when turning and can hit vehicles overtaking or passing beside them."),
("You turn left at a junction in a lorry. Which mirror must you also check?",
 "The right mirror", ["The front mirror only", "The inside mirror", "No mirror is needed"],
 "When turning left, check the right mirror too, because the rear and overhang of the lorry swing out and traffic can be beside you."),
("In a large share of crashes while a lorry turns left, what happens?",
 "A car hits it from behind", ["It hits a parked car", "A pedestrian walks into it", "It hits a cyclist ahead"],
 "Many left-turn crashes happen because cars behind run into the large vehicle as it slows down, stops or begins to turn."),
("You enter a roundabout whose surface slopes the wrong way (negative camber) too fast. What is the danger?",
 "The lorry may overturn", ["The engine may stall", "The trailer may uncouple", "The tyres may burst"],
 "Too high a speed into a roundabout with negative camber gives a high risk of overturning, especially for vehicles with a high centre of gravity."),
("Where should you position a lorry in a roundabout, whatever exit you take?",
 "As far right as possible", ["In the left lane", "On the central island apron", "Wherever there is space"],
 "Keep as far right as the roundabout's design allows, whichever exit you take, because you can see less along the lorry's right side."),
("You leave a roundabout in a tall lorry. What can raise the risk of overturning?",
 "Accelerating too early", ["Signalling left too late", "Using the right lane", "Driving too slowly"],
 "Too high a speed or accelerating too early on the way out of a roundabout also increases the risk of overturning."),
("Most crashes with large vehicles on motorways are of which kind?",
 "Catching up or hit from behind", ["Head-on collisions with oncoming traffic", "Hitting a pedestrian", "Crashing at a junction"],
 "Most motorway crashes with large vehicles happen when catching up with cars ahead, or when the large vehicle is caught up and hit from behind."),
("On a motorway with three lanes each way, when may a lorry use the left lane?",
 "Where the road forks", ["When overtaking another lorry", "When the right lanes are full", "After 22:00 at night"],
 "Lorries may only use the two right-hand lanes, but the rule does not apply where the road forks or when preparing to turn left where the motorway ends."),
("What makes motorway driving demanding in a lorry?",
 "Judging gaps and speeds", ["Steering at high speeds", "Seeing the road signs", "Finding places to stop"],
 "There are difficulties judging the distance to others and your own and others' speed, especially when catching up, as well as with the blind spots."),
("May a lorry stop on the pavement to unload?",
 "No, never", ["Yes, for up to 3 minutes", "Yes, with hazard lights on", "Yes, if no one is walking"],
 "Large vehicles may neither stop nor park on the pavement. Find a lawful place to load and unload."),
("You load goods at the roadside. What must the way you do it avoid?",
 "Danger or undue nuisance", ["Any use of the tail lift", "Opening the side doors", "Switching off the engine"],
 "Opening doors, getting in or out and loading or unloading must be done so that no danger or undue inconvenience arises."),
("Compared with daylight, how often are large vehicles involved in crashes in the dark?",
 "Relatively more often", ["Relatively less often", "About equally often", "Almost never"],
 "The poorer conditions for looking around mean large vehicles are involved in relatively more crashes in the dark than in daylight."),
("Why should you think carefully before parking a lorry on the road in the dark?",
 "It can hide others", ["The battery may run flat", "Parking lights are not allowed", "The brakes may freeze"],
 "Stopping and parking large vehicles without enough regard for others' view and safety is a risk, especially in the dark and in poor visibility."),
("You stop at a loading ramp driving forwards. How close should the side of the bed be?",
 "No more than 1 m away", ["No more than 2 m away", "Touching the ramp", "At least 3 m away"],
 "Driving forwards to a ramp, place the side of the bed no more than one metre from it."),
]
